pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Address(1) deposits 5 wei
        vm.deal(address(1), 5 wei);
        vm.prank(address(1));
        c.deposit{value: 5 wei}();
        // Address(2) deposits 3 wei
        vm.deal(address(2), 3 wei);
        vm.prank(address(2));
        c.deposit{value: 3 wei}();
        // Address(1) withdraws all
        vm.prank(address(1));
        c.withdrawAll();
        // Address(2) attempts withdrawal; wrap in try/catch to detect revert
        bool ok;
        vm.prank(address(2));
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        // In reference: succeeds (true); in buggy: reverts (false) because balance is 0
        assertTrue(ok);
    }
}

