pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(1);
        address bob = address(2);
        vm.deal(alice, 2 wei);
        vm.deal(bob, 1 wei);

        vm.prank(alice);
        c.deposit{value: 1 wei}();
        vm.prank(alice);
        c.deposit{value: 1 wei}();

        vm.prank(alice);
        c.withdrawAll();

        vm.prank(bob);
        c.deposit{value: 1 wei}();

        uint bobBalBefore = address(bob).balance;
        vm.prank(bob);
        c.withdrawAll();
        uint bobBalAfter = address(bob).balance;

        // In reference: bob gets 1 wei back, so bobBalAfter == bobBalBefore + 1 wei
        // In buggy: balance is 0 after alice's withdrawal (set to 0, then call succeeds), bob deposits 1 wei (balance becomes 1), then withdrawAll sends 1 wei but sets balance to 0, so bob's balance increases by 1 wei
        // Actually buggy: after alice withdraws, balance=0. Then bob deposits 1 wei, balance=1. Then bob withdraws: oCredit=1, balance=0, sends 1 wei, credit[bob]=0. So bob also gets 1 wei. The bug only matters for multiple withdrawals with different users? Let me re-express.
        // Actually the key: after alice's withdrawal in buggy, balance=0 (not 0 because it was 2, set to 0, but the subtraction didn't happen). Then bob deposits 1 wei, balance=1. Bob withdraws: sends 1 wei, sets balance=0. Bob gets his 1 wei. Both versions same? No: after alice's withdrawal, reference balance=0 (2-2=0), buggy balance=0 (set to 0). Then bob deposits 1 wei, both balance=1. Bob withdraws: reference balance=1-1=0, sends 1; buggy balance=0, sends 1. Bob's balance increases by 1 in both. Hmm.
        // The difference is that in reference, after alice's withdrawal, balance = 0 (correct). In buggy, balance = 0 (by assignment). Both are 0, so no divergence? Wait, the original difference: bug sets balance to 0 unconditionally, so if oCredit is 2, reference subtracts 2 making balance=0, bug sets to 0 also 0. But if oCredit is less than full balance, e.g., deposit 5, then another deposit 3, then withdraw first depositor (oCredit=5): reference balance=8-5=3, bug balance=0. So after first withdrawal, reference balance=3, bug balance=0. Then second depositor withdraws (oCredit=3): reference sends 3, balance=0; bug tries to send 3 but balance=0, call fails (insufficient funds) and reverts. 
        // So I should use that scenario: alice deposits 5, bob deposits 3, alice withdraws (reference balance=3, bug balance=0), then bob withdraws: reference succeeds (sends 3), bug reverts.
        // But this was already tried and rejected. I need a different concrete input that the bug actually breaks.
        // Let's try: alice deposits 2, bob deposits 1, alice withdraws (reference balance=1, bug balance=0), then bob withdraws: reference sends 1, bug reverts (balance=0). Assert that bob's withdraw reverts in bug but not in reference.
        // That's similar to already tried. Please provide a new scenario.
        // Actually the already tried scenarios are different amounts. But the exact boundary: deposit 1, deposit 1, withdraw first, then second deposit 1, then second withdraw: same as above.
        // The difference is that in bug, after first withdrawal, balance=0 always. So second depositor's withdrawal always fails if their oCredit > 0 and balance=0. The only way to avoid revert is if second depositor has oCredit=0. So assert that after first withdrawal, c.balance() (the public getter) returns 0 in bug but positive in reference if total deposits > first withdrawal amount.
        // Let's use: alice deposits 2, bob deposits 1. c.balance() after both deposits is 3. Then alice withdraws: reference balance=1, bug balance=0. Check c.balance() == 1 in reference but 0 in bug.
        // This is a simple getter check.
        vm.deal(alice, 2 wei);
        vm.deal(bob, 1 wei);

        vm.prank(alice);
        c.deposit{value: 2 wei}();
        vm.prank(bob);
        c.deposit{value: 1 wei}();

        vm.prank(alice);
        c.withdrawAll();

        uint balanceAfter = c.balance(); // public getter
        assertTrue(balanceAfter == 1 wei, "balance should be 1 wei in reference, not 0");
    }
}

